/* ---------- Test infrastructure ---------- */

static int testsRun = 0;
static int testsPassed = 0;

#define CHECK(cond, name) do { \
    testsRun++; \
    if (cond) { testsPassed++; printf("  [PASS] %s\n", name); } \
    else { printf("  [FAIL] %s (line %d)\n", name, __LINE__); } \
} while (0)

#define SECTION(name) printf("\n=== %s ===\n", name)

static double realOf(MatrixElement e) {
    return e.isComplex ? e.value.complex.real : e.value.real;
}

static bool approxReal(MatrixElement e, double expected, double tol) {
    double actual = realOf(e);
    return fabs(actual - expected) <= tol;
}

/* ---------- ConjugacyClass tests ---------- */

void testConstructAndFreeConjugacyClass() {
    SECTION("constructConjugacyClass / freeConjugacyClass");
    Group* Z4 = constructZnGroup(4);

    // NULL inputs
    CHECK(constructConjugacyClass(NULL, Z4->elements[0]) == NULL, "construct: NULL group");
    CHECK(constructConjugacyClass(Z4, NULL) == NULL, "construct: NULL rep");

    // Identity is its own class in any group
    ConjugacyClass* cls = constructConjugacyClass(Z4, Z4->elements[0]);
    CHECK(cls != NULL, "construct identity class");
    CHECK(cls->group == Z4, "class group pointer");
    CHECK(cls->rep == Z4->elements[0], "class rep pointer");
    CHECK(cls->size == 1, "identity class size is 1");
    CHECK(cls->elementOrder == 1, "identity element order is 1");
    CHECK(cls->indices != NULL, "class indices allocated");
    freeConjugacyClass(cls);

    // element of order 2 in Z4
    ConjugacyClass* cls2 = constructConjugacyClass(Z4, Z4->elements[2]);
    CHECK(cls2 != NULL, "construct order-2 class");
    CHECK(cls2->size == 1, "Z4: each class has size 1 (abelian)");
    CHECK(cls2->elementOrder == 2, "element 2 has order 2 in Z4");
    freeConjugacyClass(cls2);

    // free(NULL) should be safe
    freeConjugacyClass(NULL);
    CHECK(1, "freeConjugacyClass(NULL) does not crash");

    freeGroup(Z4);
}

